&lt;/div&gt;
&lt;div class=&quot;a1&quot;&gt;&lt;a href=&quot;https://appinio.com/&quot; target=&quot;_blank&quot;&gt;&lt;img style=&quot;max-width: 100%;&quot; src=&quot;https://jobdata.prescreen.io/appinio/website-icon.svg&quot;&gt;&amp;nbsp;appinio.com&amp;nbsp; &amp;nbsp;&lt;/a&gt;&lt;a href=&quot;https://de.linkedin.com/company/appinio-gmbh&quot; target=&quot;_blank&quot;&gt;&lt;img style=&quot;max-width: 100%;&quot; src=&quot;https://jobdata.prescreen.io/appinio/linkedin-icon.svg&quot;&gt;&amp;nbsp;LinkedIn &amp;nbsp;&amp;nbsp;&lt;/a&gt;&lt;a href=&quot;https://www.xing.com/companies/appiniogmbh&quot; target=&quot;_blank&quot;&gt;&lt;img style=&quot;max-width: 100%;&quot; src=&quot;https://jobdata.prescreen.io/appinio/xing-icon.svg&quot;&gt;&amp;nbsp;Xing&amp;nbsp; &amp;nbsp;&amp;nbsp;&lt;/a&gt;&lt;a href=&quot;https://www.kununu.com/de/appinio&quot; target=&quot;_blank&quot;&gt;&lt;img style=&quot;max-width: 100%;&quot; src=&quot;https://jobdata.prescreen.io/appinio/kununu-icon.svg&quot;&gt;&amp;nbsp;Kununu &amp;nbsp;&amp;nbsp;&lt;/a&gt;&lt;a href=&quot;https://www.instagram.com/appinio&quot; target=&quot;_blank&quot;&gt;&lt;img style=&quot;max-width: 100%;&quot; src=&quot;https://jobdata.prescreen.io/appinio/instagram-icon.svg&quot;&gt;&amp;nbsp;Instagram&lt;/a&gt;&lt;/div&gt;
